// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testRegression_property() public {
        MockERC20 token = new MockERC20();
        token.mint(address(c), 100);

        c.AdjustBetAmounts(100);

        bool success = c.transferAnyERC20Token(address(token), address(this), 100);


        assertTrue(success == true);
    }
}

interface ERC20Interface {
    function transfer(address to, uint256 tokens) external returns (bool success);
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;

    function mint(address to, uint256 amount) public {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 tokens) public returns (bool success) {
        require(balanceOf[msg.sender] >= tokens);
        require(tokens > 0);
        balanceOf[msg.sender] -= tokens;
        balanceOf[to] += tokens;
        return true;
    }
}
